import re
from datetime import timedelta, timezone

from logkeep import streams
from logkeep.errors import DataError

DEFAULTS = {
    "max_size": None,
    "max_age": None,
    "naming": "numbered",
    "offset": timezone.utc,
    "compress_after": 1,
    "keep": 5,
    "keep_days": None,
}

_NUMBER = re.compile(r"[0-9]+")
_SIZE = re.compile(r"([0-9]+)([KMGkmg]?)")
_AGE = re.compile(r"([0-9]+)([mhd])")
_OFFSET = re.compile(r"([+-])([0-9]{2}):([0-9]{2})")
_UNITS = {"": 1, "k": 1024, "m": 1024**2, "g": 1024**3}
_SPANS = {"m": timedelta(minutes=1), "h": timedelta(hours=1), "d": timedelta(days=1)}


def _fail(message):
    raise DataError("policy", f"policy.ini: {message}")


def _size(text):
    if text == "off":
        return None
    match = _SIZE.fullmatch(text)
    if not match:
        _fail(f"bad size {text!r}")
    return int(match.group(1)) * _UNITS[match.group(2).lower()]


def _age(text):
    if text == "off":
        return None
    match = _AGE.fullmatch(text)
    if not match:
        _fail(f"bad duration {text!r}")
    return int(match.group(1)) * _SPANS[match.group(2)]


def _naming(text):
    if text not in ("numbered", "dated"):
        _fail(f"bad naming {text!r}")
    return text


def _offset(text):
    match = _OFFSET.fullmatch(text)
    if not match or int(match.group(2)) > 23 or int(match.group(3)) > 59:
        _fail(f"bad offset {text!r}")
    delta = timedelta(hours=int(match.group(2)), minutes=int(match.group(3)))
    return timezone(-delta if match.group(1) == "-" else delta)


def _number(minimum):
    def parse(text):
        if not _NUMBER.fullmatch(text) or int(text) < minimum:
            _fail(f"bad number {text!r}")
        return int(text)

    return parse


def _keep_days(text):
    return None if text == "off" else _number(1)(text)


PARSERS = {
    "max_size": _size,
    "max_age": _age,
    "naming": _naming,
    "offset": _offset,
    "compress_after": _number(0),
    "keep": _number(1),
    "keep_days": _keep_days,
}


class Policy:
    def __init__(self, defaults: dict, sections: dict):
        self.defaults = defaults
        self.sections = sections

    def stream_names(self):
        return set(self.sections)

    def settings(self, name: str) -> dict:
        out = dict(DEFAULTS)
        out.update(self.defaults)
        out.update(self.sections.get(name, {}))
        return out


