                if name in sections:
                    _fail(f"section {name} twice")
                sections[name] = current = {}
            else:
                _fail(f"unknown section {title!r}")
            continue
        if current is None or "=" not in line:
            _fail(f"bad line {line!r}")
        key, value = (part.strip() for part in line.split("=", 1))
        if key not in PARSERS:
            _fail(f"unknown key {key!r}")
        if key in current:
            _fail(f"key {key} twice")
        current[key] = PARSERS[key](value)
    return Policy(defaults or {}, sections)
