"""rotate (docs/rotate.md)."""

import gzip
import re
from datetime import date, timedelta

from logkeep import dates, policy, state, streams
from logkeep.errors import DataError, Refused

_NUMBERED = re.compile(r"([1-9][0-9]*)(\.gz)?", re.ASCII)
_DATED = re.compile(r"([0-9]{4}-[0-9]{2}-[0-9]{2})(?:\.([2-9]|[1-9][0-9]+))?(\.gz)?", re.ASCII)


class Archive:
    def __init__(self, name, key, day, count, compressed):
        self.name = name
        self.key = key
        self.day = day
        self.count = count
        self.compressed = compressed
        self.new = False
        self.removed = False
        self.final = None
        self.time = None
        self.data = None
        self.becomes_compressed = compressed


def _archives(logs, name, naming):
    prefix = f"{name}.log."
    found = {}
    if logs.is_dir():
        for path in logs.iterdir():
            if not path.name.startswith(prefix) or not path.is_file():
                continue
            rest = path.name[len(prefix):]
            if naming == "numbered":
                match = _NUMBERED.fullmatch(rest)
                if not match:
                    continue
                key = (int(match.group(1)),)
                arc = Archive(path.name, key, None, None, bool(match.group(2)))
            else:
                match = _DATED.fullmatch(rest)
                if not match:
                    continue
                try:
                    day = date.fromisoformat(match.group(1))
                except ValueError:
                    continue
                count = int(match.group(2) or 1)
                arc = Archive(path.name, (day, count), day, count, bool(match.group(3)))
            if arc.key in found:
                raise DataError("archives", f"{name}: two archives in the same place")
            found[arc.key] = arc
    ordered = sorted(found.values(), key=lambda arc: arc.key)
    return ordered if naming == "numbered" else ordered[::-1]


def _check_state(doc, existing):
    for name in existing:
        entry = doc["streams"].get(name)
        if entry is None:
            continue
        try:
            if "opened" in entry:
                dates.parse_state_time(entry["opened"])
            archives = entry.get("archives", {})
            if not isinstance(archives, dict):
                raise ValueError("archives")
            for value in archives.values():
                dates.parse_state_time(value)
            rotations = entry.get("rotations", 0)
            if isinstance(rotations, bool) or not isinstance(rotations, int) or rotations < 0:
                raise ValueError("rotations")
        except ValueError:
            raise DataError("state", f"state.json: bad entry {name}") from None


def _opened(entry, read_log):
    if "opened" in entry:
        return dates.parse_state_time(entry["opened"])
    first = read_log().split(b"\n", 1)[0].rstrip(b"\r")
    try:
        return dates.parse_line_time(first.decode("utf-8").split(" ", 1)[0])
    except (ValueError, UnicodeDecodeError):
        return None


def _decide(settings, size, entry, read_log, now, force):
    if size is None:
        return "no log"
    if size == 0:
        return "empty"
    if force:
        return "forced"
    if settings["max_size"] is not None and size >= settings["max_size"]:
        return "size"
    if settings["max_age"] is not None:
        opened = _opened(entry, read_log)
        if opened is not None and now - opened >= settings["max_age"]:
            return "age"
    return "not due"


def _plan(ctx, name, settings, entry, force):
    logs = streams.logs_dir(ctx.data)
    log = streams.log_path(ctx.data, name)
    size = log.stat().st_size if log.is_file() else None
    cache = []

    def read_log():
        if not cache:
            cache.append(log.read_bytes())
        return cache[0]

    what = _decide(settings, size, entry, read_log, ctx.now, force)
    rotated = what not in ("no log", "empty", "not due")
    naming = settings["naming"]
    archives = _archives(logs, name, naming)
    old_times = entry.get("archives", {})
    for arc in archives:
        arc.time = old_times.get(arc.name)
    if rotated:
        if naming == "numbered":
            new = Archive(None, None, None, None, False)
        else:
            day = ctx.now.astimezone(settings["offset"]).date()
            counts = [arc.count for arc in archives if arc.day == day]
            new = Archive(None, None, day, max(counts) + 1 if counts else 1, False)
        archives.insert(0, new)
        new.new = True
        new.time = dates.stamp(ctx.now)
        new.data = read_log()
    for position, arc in enumerate(archives, 1):
        if position > settings["keep"]:
            arc.removed = True
        elif settings["keep_days"] is not None and arc.time is not None:
            when = dates.parse_state_time(arc.time)
            if ctx.now - when >= timedelta(days=settings["keep_days"]):
                arc.removed = True
    kept = [arc for arc in archives if not arc.removed]
    compressed = 0
    for position, arc in enumerate(kept, 1):
        arc.becomes_compressed = arc.compressed or position > settings["compress_after"]
        if arc.becomes_compressed and not arc.compressed:
            compressed += 1
        suffix = ".gz" if arc.becomes_compressed else ""
        if naming == "numbered":
            arc.final = f"{name}.log.{position}{suffix}"
        else:
            tail = f".{arc.count}" if arc.count > 1 else ""
            arc.final = f"{name}.log.{arc.day.isoformat()}{tail}{suffix}"
    lines = [f"{name}: rotate ({what})" if rotated else f"{name}: {what}"]
    for arc in kept:
        if arc.new:
            lines.append(f"  new {arc.final}")
        elif arc.final != arc.name:
            lines.append(f"  {arc.final} <- {arc.name}")
        else:
            lines.append(f"  {arc.name}")
    removed = [arc for arc in archives if arc.removed]
    for arc in removed:
        lines.append(f"remove {arc.name}")
    new_entry = {}
    if rotated:
        new_entry["opened"] = dates.stamp(ctx.now)
    elif "opened" in entry:
        new_entry["opened"] = entry["opened"]
    new_entry["rotations"] = entry.get("rotations", 0) + (1 if rotated else 0)
    new_entry["archives"] = {arc.final: arc.time for arc in kept if arc.time is not None}
    return {"lines": lines, "rotated": rotated, "removed": len(removed), "compressed": compressed,
            "archives": archives, "entry": new_entry, "log": log}


def _apply(logs, plans):
    writes = []
    deletes = []
    for plan in plans:
        for arc in plan["archives"]:
            if arc.removed:
                deletes.append(logs / arc.name)
            elif arc.new:
                content = arc.data
                if arc.becomes_compressed:
                    content = gzip.compress(content, mtime=0)
                writes.append((logs / arc.final, content))
            elif arc.final != arc.name:
                content = (logs / arc.name).read_bytes()
                if arc.becomes_compressed and not arc.compressed:
                    content = gzip.compress(content, mtime=0)
                deletes.append(logs / arc.name)
                writes.append((logs / arc.final, content))
        if plan["rotated"]:
            writes.append((plan["log"], b""))
    for path in deletes:
        path.unlink()
    for path, content in writes:
        path.write_bytes(content)


def cmd_rotate(ctx, args, check_stream):
    requested = sorted({check_stream(text) for text in args.streams})
    pol = policy.load(ctx.policy_path)
    existing = set(streams.active(ctx.data)) | pol.stream_names()
    doc = ctx.state
    _check_state(doc, existing)
    for name in requested:
        if name not in existing:
            raise Refused("unknown-stream", f"no stream {name}")
    names = requested if requested else sorted(existing)
    plans = [_plan(ctx, name, pol.settings(name), doc["streams"].get(name, {}), args.force) for name in names]
    lines = []
    for plan in plans:
        lines.extend(plan["lines"])
    lines.append(f"{sum(p['rotated'] for p in plans)} rotated, {sum(p['removed'] for p in plans)} removed, "
                 f"{sum(p['compressed'] for p in plans)} compressed")
    if args.dry_run:
        lines.append("dry run: nothing written")
        return lines
    _apply(streams.logs_dir(ctx.data), plans)
    for name, plan in zip(names, plans):
        doc["streams"][name] = plan["entry"]
    state.save(ctx.state_path, doc)
    return lines
